export function parseLines(text: string): unknown[] {
  // Strip a single leading UTF-8 BOM; any further BOM is left as record content.
  const source = text.charCodeAt(0) === 0xfeff ? text.slice(1) : text
  const rows: unknown[] = []
  const lines = source.split(/\r?\n/)
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    // Blank/whitespace-only lines are not records. The empty tail produced by a
    // trailing newline is skipped by the same check.
    if (line.trim() === "") continue
    try {
      rows.push(JSON.parse(line))
    } catch (cause) {
      const detail = cause instanceof Error ? cause.message : String(cause)
      throw new Error(`Invalid JSON on line ${i + 1}: ${detail}`)
    }
  }
  return rows
}
