interface Job { work: () => Promise<unknown>; resolve: (value: unknown) => void; reject: (error: unknown) => void }
export class WorkQueue {
  private jobs: Job[] = []
  private running = 0
  constructor(private concurrency = 1) {}
  get active(): number { return this.running }
  get pending(): number { return this.jobs.length }
  run<T>(work: () => Promise<T>, _options: { priority?: number; signal?: AbortSignal } = {}): Promise<T> {
    return new Promise((resolve, reject) => { this.jobs.push({ work, resolve: resolve as (value: unknown) => void, reject }); this.drain() })
  }
  private drain(): void {
    while (this.running < this.concurrency && this.jobs.length) {
      const job = this.jobs.shift()!
      this.running++
      let settled = false
      const finish = (settle: () => void): void => {
        if (settled) return
        settled = true
        this.running--
        settle()
        this.drain()
      }
      Promise.resolve().then(job.work).then(
        (value) => finish(() => job.resolve(value)),
        (error) => finish(() => job.reject(error)),
      )
    }
  }
}

