import { expect, test } from "bun:test"
import { WorkQueue } from "../src/index"

test("frees slot after rejection and keeps running", async () => {
  const queue = new WorkQueue(2)
  const seen: string[] = []
  const failing = queue.run(async () => { throw new Error("boom") })
  const passing = queue.run(async () => { seen.push("pass"); return 2 })
  const after = queue.run(async () => { seen.push("after"); return 3 })
  await expect(failing).rejects.toThrow("boom")
  expect(await passing).toBe(2)
  expect(await after).toBe(3)
  expect(seen).toEqual(["pass", "after"])
  expect(queue.active).toBe(0)
  expect(queue.pending).toBe(0)
})

test("frees slot after synchronous throw", async () => {
  const queue = new WorkQueue(1)
  const sync = queue.run((() => { throw new Error("sync") }) as unknown as () => Promise<never>)
  const next = queue.run(async () => 7)
  await expect(sync).rejects.toThrow("sync")
  expect(await next).toBe(7)
  expect(queue.active).toBe(0)
  expect(queue.pending).toBe(0)
})

test("settles each promise once and respects concurrency", async () => {
  const queue = new WorkQueue(2)
  let inFlight = 0
  let maxInFlight = 0
  const tasks = Array.from({ length: 10 }, (_, i) =>
    queue.run(async () => {
      inFlight++
      maxInFlight = Math.max(maxInFlight, inFlight)
      await new Promise((r) => setTimeout(r, 5))
      inFlight--
      if (i % 3 === 0) throw new Error(`e${i}`)
      return i
    }),
  )
  const results = await Promise.allSettled(tasks)
  expect(results.every((r) => r.status === "fulfilled" || r.status === "rejected")).toBe(true)
  expect(maxInFlight).toBeLessThanOrEqual(2)
  expect(queue.active).toBe(0)
  expect(queue.pending).toBe(0)
})
